<script setup lang="ts">
// generated by AI (GitHub Copilot, DeepSeek V4 Flash Vision Exp)
// Root component: databases -> unlock -> accounts, with a toolbar once
// unlocked. Any click resets the auto-lock idle timer.

import { t } from '@nextcloud/l10n';
import { onMounted, ref } from 'vue';

import {
  activeDescriptor,
  lock,
  selectDatabase,
  selectedDatabase,
  touch,
  unlocked,
} from '../state/session';
import { restoreLastOpened } from '../storage/resume';
import AccountsView from './AccountsView.vue';
import DatabasesView from './DatabasesView.vue';
import ExportButton from './ExportButton.vue';
import SyncButton from './SyncButton.vue';
import UnlockView from './UnlockView.vue';

/** True until the last opened database (if any) has been selected. */
const booting = ref(true);

onMounted(async () => {
  try {
    const descriptor = await restoreLastOpened();
    if (descriptor !== null) {
      selectDatabase(descriptor);
    }
  } catch {
    // A failed restore is not fatal: the database list is shown instead.
  } finally {
    booting.value = false;
  }
});

function onLock(): void {
  lock();
}

/** Return to the database list (locking first when a database is open). */
function onChangeDatabase(): void {
  lock();
  selectDatabase(null);
}
</script>

<template>
  <div
    class="upm-app"
    style="
      padding: 20px;
      background-color: var(--color-main-background);
      color: var(--color-main-text);
      border-radius: var(--border-radius-large, 8px);
      box-shadow: 0 1px 4px rgba(0, 0, 0, 0.15);
      max-width: 1000px;
      max-height: calc(100vh - var(--header-height, 50px) - 24px);
      overflow-y: auto;
      scrollbar-width: thin;
    "
    @click="touch"
    @keydown="touch"
  >
    <p v-if="booting" style="opacity: 0.7">{{ t('upm', 'Loading…') }}</p>
    <DatabasesView v-else-if="!selectedDatabase" />
    <UnlockView v-else-if="!unlocked" />
    <template v-else>
      <div style="display: flex; gap: 8px; align-items: center; margin-bottom: 12px">
        <button type="button" class="button" @click="onLock">{{ t('upm', 'Lock') }}</button>
        <SyncButton />
        <ExportButton />
        <button type="button" class="button" @click="onChangeDatabase">
          {{ t('upm', 'Change database') }}
        </button>
      </div>
      <p v-if="activeDescriptor" style="opacity: 0.7; margin-top: 0">
        {{ activeDescriptor.label }}
        <span v-if="activeDescriptor.path !== activeDescriptor.label">
          — {{ activeDescriptor.path }}
        </span>
      </p>
      <AccountsView />
    </template>
  </div>
</template>
